import React, { useState, useEffect } from 'react';
import { NavLink, Outlet, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faTachometerAlt, faUserGraduate, faChalkboardTeacher, faMoneyBillWave, faCog, faQuestionCircle, faChevronLeft, faChevronRight, faSearch, faBell, faEnvelope, faChevronDown, faSun, faMoon, faCalendarAlt, faClipboardList, faSignOutAlt, faUserCircle, faUserTag, faCamera, faUpload } from '@fortawesome/free-solid-svg-icons';
import './../assets/css/dashboard-content.css';
import './../assets/css/profile.css';

const Profile = () => {
    const [isCollapsed, setIsCollapsed] = useState(false);
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const [isDarkMode, setIsDarkMode] = useState(false);
    const [user, setUser] = useState(null);
    const [photo, setPhoto] = useState(null);
    const navigate = useNavigate();

    useEffect(() => {
        const fetchUserData = async () => {
            try {
                const token = localStorage.getItem('token');
                const res = await axios.get('http://localhost:5000/api/auth/me', {
                    headers: {
                        'x-auth-token': token
                    }
                });
                setUser(res.data);
            } catch (err) {
                console.error(err);
                alert('Failed to fetch user data.');
            }
        };

        fetchUserData();
    }, []);

    const toggleSidebar = () => {
        setIsCollapsed(!isCollapsed);
    };

    const toggleDropdown = () => {
        setIsDropdownOpen(!isDropdownOpen);
    };

    const toggleDarkMode = () => {
        setIsDarkMode(!isDarkMode);
    };

    const handleLogout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('role');
        navigate('/login');
    };

    const handlePhotoChange = (e) => {
        setPhoto(e.target.files[0]);
    };

    const handlePhotoUpload = async () => {
        if (!photo) {
            alert('Please select a photo to upload.');
            return;
        }

        const formData = new FormData();
        formData.append('photo', photo);

        try {
            const token = localStorage.getItem('token');
            await axios.post('http://localhost:5000/api/auth/upload-photo', formData, {
                headers: {
                    'Content-Type': 'multipart/form-data',
                    'x-auth-token': token
                }
            });
            alert('Photo uploaded successfully!');
        } catch (err) {
            console.error(err);
            alert('Failed to upload photo.');
        }
    };

    if (!user) {
        return <div>Loading profile...</div>;
    }

    return (
        <div className={`dashboard-container ${isDarkMode ? 'dark-mode' : ''}`}>
            {/* Sidebar */}
            <aside className={`sidebar ${isCollapsed ? 'collapsed' : ''}`}>
                <div className="sidebar-header">
                    <h1 className="app-logo">ECA</h1>
                    <button className="collapse-btn" onClick={toggleSidebar}>
                        <FontAwesomeIcon icon={isCollapsed ? faChevronRight : faChevronLeft} />
                    </button>
                </div>
                <nav className="sidebar-menu">
                    <NavLink to="/admin-dashboard" end className="sidebar-menu-item" activeClassName="selected">
                        <FontAwesomeIcon icon={faTachometerAlt} />
                        {!isCollapsed && <span>Dashboard</span>}
                    </NavLink>
                    <NavLink to="/admin-dashboard/students" className="sidebar-menu-item" activeClassName="selected">
                        <FontAwesomeIcon icon={faUserGraduate} />
                        {!isCollapsed && <span>Student Management</span>}
                    </NavLink>
                    <NavLink to="/admin-dashboard/teachers" className="sidebar-menu-item" activeClassName="selected">
                        <FontAwesomeIcon icon={faChalkboardTeacher} />
                        {!isCollapsed && <span>Teacher Management</span>}
                    </NavLink>
                    <NavLink to="/admin-dashboard/fees" className="sidebar-menu-item" activeClassName="selected">
                        <FontAwesomeIcon icon={faMoneyBillWave} />
                        {!isCollapsed && <span>Fee Management</span>}
                    </NavLink>
                    <NavLink to="/admin-dashboard/courses" className="sidebar-menu-item" activeClassName="selected">
                        <FontAwesomeIcon icon={faCog} />
                        {!isCollapsed && <span>Courses</span>}
                    </NavLink>
                </nav>
                <div className="sidebar-footer">
                    <div className="sidebar-footer-item">
                        <FontAwesomeIcon icon={faQuestionCircle} />
                        {!isCollapsed && <span>Help & Support</span>}
                    </div>
                    <button className="logout-btn" onClick={handleLogout}>
                        <FontAwesomeIcon icon={faSignOutAlt} />
                        {!isCollapsed && <span>Logout</span>}
                    </button>
                </div>
            </aside>

            {/* Main Content Area */}
            <main className={`main-content ${isCollapsed ? 'full-width' : ''}`}>
                {/* Header Section */}
                <header className="dashboard-header-main">
                    <div className="search-bar-container">
                        <input type="text" placeholder="Search" className="search-input" />
                        <FontAwesomeIcon icon={faSearch} className="search-icon" />
                    </div>
                    <div className="header-right">
                        <FontAwesomeIcon icon={faEnvelope} className="header-icon" />

                        {/* Dark Mode Toggle Button */}
                        <button className="theme-toggle-btn" onClick={toggleDarkMode}>
                            <FontAwesomeIcon icon={isDarkMode ? faSun : faMoon} />
                        </button>

                        <div className="profile-dropdown-container">
                            <div className="profile-trigger" onClick={toggleDropdown}>
                                <img src={user.photo || '/path/to/default-profile-pic.png'} alt="Profile" className="profile-pic-header" />
                                <div className="profile-info-header">
                                    <p className="profile-name-header">{user.name}</p>
                                    <p className="profile-role-header">{user.role}</p>
                                </div>
                                <FontAwesomeIcon icon={faChevronDown} className="dropdown-arrow" />
                            </div>
                            {isDropdownOpen && (
                                <div className="dropdown-menu">
                                    <NavLink to="/admin-dashboard/profile" className="dropdown-item" onClick={toggleDropdown}>Profile</NavLink>
                                    <NavLink to="/admin-dashboard/change-password" className="dropdown-item" onClick={toggleDropdown}>Change Password</NavLink>
                                    <button className="dropdown-item" onClick={handleLogout}>Logout</button>
                                </div>
                            )}
                        </div>
                    </div>
                </header>

                <div className="profile-container">
                    <h2>User Profile</h2>
                    <div className="profile-details">
                        <div className="profile-photo">
                            <img
                                src={user.photo || 'https://via.placeholder.com/150'}
                                alt="User Profile"
                            />
                            <div className="photo-upload-section">
                                <input type="file" onChange={handlePhotoChange} />
                                <button onClick={handlePhotoUpload}>Upload Photo</button>
                            </div>
                        </div>
                        <div className="user-info">
                            <p><strong>Name:</strong> {user.name}</p>
                            <p><strong>Email:</strong> {user.email}</p>
                            <p><strong>Role:</strong> {user.role}</p>
                        </div>
                    </div>
                </div>
            </main>
        </div>
    );
};

export default Profile;
